entries[273851] = { ["name"] = "Seelentresor", ["text"] = "Wirken in 2 sek.\nWenn eine Seele aus dem Jenseits zurückgerufen wird, kann sie sich auf der materiellen Ebene frei bewegen, solange sie nicht sofort nach ihrer Ankunft gebunden wird. Die Drust erschufen Gefängnisse für diese Seelen, um sie später in ihren dunklen Ritualen zu nutzen. Bis dahin litten sie in Thros, bis ihre ursprüngliche Identität vollkommen entstellt war." }
entries[273852] = { ["name"] = "Tanz der Toten", ["text"] = "Wirken in 2 sek.\nWenn die Drust Gegner oder Beute ablenken wollten, platzierten sie oft unauffällig sonderbare kleine Objekte in der jeweiligen Umgebung. Beim Aufheben und Betrachten beschworen diese Objekte dann die entsetzliche Vision eines tanzenden Schreckgespensts. Dieses Schreckgespenst zog alle Zuschauer in seinen Bann und machte sie gefügig, wodurch man kurzen Prozess mit ihnen machen konnte.\nTanz der Toten\nWird beim Aufheben gebunden\nSpielzeug\nBenutzen: Beschwört eine geisterhafte tanzende Hexe. (10 Min Abklingzeit)" }
entries[273853] = { ["name"] = "Sandsturm", ["text"] = "Eure Zauber und Fähigkeiten haben eine Chance, einen Wirbel aus stechenden Winden zu erschaffen. Gegner innerhalb des Wirbels erleiden alle 2 Sek. 68 Schaden und fügen Euch um 228 verringerten Schaden zu." }
entries[273854] = { ["name"] = "Zusammengeflickter Wiedergänger", ["text"] = "Wirken in 2 sek.\nAls die Drust besser darin wurden, Seelen in Objekten einzufangen, entwickelten sich auch die Todeskonstrukte, in denen sie die Seelen einfingen. Wiedergänger gehören zu den grimmigsten dieser Kreaturen. Ohne Erinnerung und jegliche Ähnlichkeit zu ihrem früheren Ich wurden sie aus Teilen zusammengesetzt, die nicht mehr verwesen konnten. Diese Kreaturen wurden niemals müde und konnten ihrer Beute bis in alle Ewigkeit nachjagen.\nKnochenhaufen\nWird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man einen zusammengeflickten Wiedergänger beschwört und wieder freigibt.\nMit Rechtsklick Euren zusammengeflickten Wiedergänger beschwören oder wieder freigeben.\n1 - 80 ( 80)" }
entries[273855] = { ["name"] = "Fetisch des gequälten Geistes", ["text"] = "Wirken in 2 sek.\nDieser Fetisch diente dazu, die Gemüter der Gegner zu verwirren und in ihnen wie Unkraut Zweifel wachsen zu lassen, die positive Gedanken überwucherten. Die Betroffenen hinterfragten ihre Beweggründe, ihre Ideale oder ihren Mut und fanden schneller die scharfe Seite einer Drustklinge als neue Entschlossenheit.\nFetisch des gequälten Geistes\nWird an Kriegsmeute gebunden\nEinzigartig anlegbarSchmuck\n+6 Ausdauer\nBenutzen: Verringert das Angriffs- und Zaubertempo des aktuellen gegnerischen Ziels für 5 Sek. um 15%. (1 Min, 30 Sek. Abklingzeit)\n45" }
